cd /Users/kristinarash/Library/Caches/sportsci-batch-96 && python3 -I -c "
import json
inp={d['id']:d['sourceFile'] for d in json.load(open('inputs.json'))}
tax=json.load(open('taxonomy.json'))
for i in ['Q49','Q50','Q51','Q52','Q53','Q54','Q55','Q56']:
    p=f'drafts/{i}.json'
    d=json.load(open(p))
    d['sourceFile']=inp[i]
    json.dump(d,open(p,'w'),ensure_ascii=False,indent=1)
    errs=[]
    if d['decision']!='EXCLUDE':
        for k in ['studyDesign','primaryDomain']:
            if d[k] not in tax[{'studyDesign':'studyDesigns','primaryDomain':'domains'}[k]]: errs.append(k)
        for k,t in [('domains','domains'),('audiences','audiences'),('sports','sports'),('populations','populations')]:
            for v in d[k]:
                if v not in tax[t]: errs.append((k,v))
        if d['primaryDomain'] not in d['domains']: errs.append('primary not in domains')
    print(i, d['sourceFile']==inp[i], 'OK' if not errs else errs)
"; echo; cd drafts && grep -c "" Q5*.json | head -1 >/dev/null

